  window.LESSONS["u5_l07"] = {"meta":{"grade":3,"subject":"수학","term":2,"unit":5,"unit_title":"들이와 무게","n":7,"title":"무게를 어림하고 재어 볼까요","std":"[4수03-04]","duration_min":40,"lesson_format":"교사주도 — 무게 어림·저울 읽기 · 2세대 19장(7요소)","theme":"곰이·펭이 재활용 알뜰 시장","live_url":"../../grade3/semester2/math/5단원_들이와무게/g3_math_u5_l07_무게를어림하고재어볼까요.html","source":"grade3/semester2/math/5단원_들이와무게/g3_math_u5_l07_무게를어림하고재어볼까요.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"무게를 어림하고 재어 볼까요\n아는 무게와 견주어요","emoji":"🧼"},"suggested_extras":["v_l7_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 무게의 단위 **1 kg = 1000 g**, **1 t = 1000 kg**을 알고 저울의 눈금을 읽었어요.","items":[{"q":"5 kg 200 g은 몇 g인가요?","a":"5200"},{"q":"7300 g은 몇 kg 몇 g인가요? kg 앞에 올 수를 쓰세요.","a":"7"},{"q":"2 t은 몇 kg인가요?","a":"2000"}],"from":"u5_l06"},"suggested_extras":["q_l7_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"폐식용유로 빨랫비누를 만들어요","kids":[{"face":"🐻","label":"곰이\n\"비누 한 상자는 얼마나 무거울까?\""},{"face":"🐧","label":"펭이\n\"밀가루 1 kg이랑 비슷해 보여\""}],"question":"폐식용유를 재활용해 **빨랫비누**를 만들었어요. 비누 한 상자의 무게를 재 보기 전에 얼마쯤인지 어림할 수 있을까요? 무엇과 견주면 좋을까요?","img":"assets/photo/math/soap_making.jpg","tnote":{"ask":["알고 있는 무게 가운데 견줄 만한 것은?","비누 하나가 약 100 g이면 10개는 얼마쯤일까요?"],"watch":"어림을 「그냥 아무 수」로 말하는 경우 — 기준을 말하게 할 것","min":3}},"suggested_extras":["q_l7_2","r_l7_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"eq","lines":["가정용 저울 · 전자저울","손저울 · 체중계","클립 1개 — 약 1 g"],"tag":"가벼운 물건은 눈금이 촘촘한 저울로"},"title":"무게를 재는 도구","content":"가정용 저울, 전자저울, 손저울, 체중계로 무게를 재요.\n클립 1개는 약 1 g이에요.\n가벼운 물건은 눈금이 촘촘한 저울로 재요.","tnote":{"ask":["어떤 무게를 잴 때 체중계를 쓰나요?","클립 1개는 약 몇 g인가요?"],"watch":"모든 물건을 같은 저울로 재려는 경우","min":4}},"suggested_extras":["e_l7_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"dial","max":10,"step":1,"v":5,"unit":"kg"},"title":"저울의 눈금을 읽어요","content":"이 저울은 0부터 10 kg까지 재고 **한 칸이 1 kg**이에요.\n바늘이 다섯 번째 칸을 가리켜서 가방의 무게는 5 kg이에요.","tnote":{"ask":["이 저울은 몇 kg까지 잴 수 있나요?","눈금 한 칸은 몇 kg인가요?"],"watch":"바늘이 가리키는 칸 수와 무게를 다르게 읽는 경우","min":4}},"suggested_extras":["t_l7_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"dial","max":1000,"step":20,"v":360,"major":100,"label":"어림 약 400 g → 재어 보니"},"title":"어림하고 재어 견주어요","content":"필통을 약 400 g으로 어림하고 재어 보니 360 g이었어요.\n어림한 값과 잰 값이 달라도 괜찮아요.\n**무엇과 견주어 어림했는지**가 중요해요.","tnote":{"ask":["어림한 값과 잰 값의 차이는?","무엇과 견주어 약 400 g으로 어림했을까요?"],"watch":"어림과 잰 값이 다르면 틀렸다고 여기는 경우","min":4}},"suggested_extras":["e_l7_2","t_l7_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"eq","lines":["자동차 — 약 1 t","강아지 — 약 10 kg","김치 반 포기 — 약 500 g"],"tag":"무게에 알맞은 단위"},"title":"알맞은 단위","content":"자동차처럼 아주 무거우면 t, 강아지는 kg, 김치 반 포기처럼 가벼우면 g을 써요.\n자동차는 약 1 t, 강아지는 약 10 kg, 김치 반 포기는 약 500 g이에요.","tnote":{"ask":["강아지 무게에 t을 쓰면 어떨까요?","김치 반 포기는 왜 g으로 나타낼까요?"],"watch":"강아지를 약 10 g으로 나타내는 경우","min":4}},"suggested_extras":["q_l7_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"책상의 무게는 **약 15 g**이다.","right":"15 g은 클립 15개쯤이라 아주 가벼워요. 책상은 혼자 들기 힘들 만큼 무거우니 **약 15 kg**이 알맞아요.","hint":"1 g(클립) · 1 kg(설탕 봉지) · 1 t(자동차) 세 기준 카드를 칠판에 붙이고 견주게 하세요.","tnote":{"ask":["15 g은 무엇 몇 개쯤인가요?","책상은 어느 기준 카드와 가까운가요?"],"watch":"수만 보고 단위를 아무렇게나 붙이는 경우","min":3}},"suggested_extras":["x_l7_1","x_l7_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🧮","body":"코끼리는 아주 무거워요."},"question":"코끼리의 무게는 약 3 ○ 예요. ○ 에 알맞은 단위는 무엇일까요?","options":[{"text":"kg"},{"text":"t","correct":true},{"text":"g"},{"text":"mL"}],"note":"풀이: 코끼리는 아주 무거워요. 1000 kg보다 무거운 무게는 어떤 단위로 나타낼까요? → **t**"},"suggested_extras":["t_l7_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🧮","body":"50 g이 10번이에요."},"question":"50 g인 공책 10권의 무게는 몇 g일까요?","input":"count_input","answer":500,"note":"풀이: 50 g이 10번이에요. 50을 10번 더하면 얼마인가요? → **500**"},"suggested_extras":["e_l7_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🧮","body":"손바닥에 올려도 거의 느껴지지 않는 물건을 찾아요."},"question":"무게가 약 1 g인 물건은 무엇일까요?","options":[{"text":"사과 1개"},{"text":"클립 1개","correct":true},{"text":"책가방 1개"},{"text":"수박 1통"}],"note":"풀이: 1 g은 아주 가벼워요. 손바닥에 올려도 거의 느껴지지 않는 물건을 찾아요. → **클립 1개**"},"suggested_extras":["q_l7_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"20 g인 지우개 5개의 무게는 몇 g일까요?","a":"100","steps":["20 g이 5번이에요","20 × 5 = 100","100 g"]},"도전":{"q":"약 300 g인 사과 3개의 무게는 약 몇 g일까요?","a":"약 900 g","steps":["약 300 g이 3번이에요","300 × 3 = 900","약 900 g"]},"심화":{"q":"내 책가방의 무게를 어림하고, 어림한 방법(견주기·몇 번인지 세기·합하기) 가운데 무엇을 썼는지 설명해 봐요.","a":"여러 답 (1 kg 설탕 봉지 3개쯤이라 약 3 kg — 견주기)","open":true}},"tnote":{"ask":["도전에서 「약」을 붙였나요?","심화에서 어떤 방법으로 어림했나요?"],"watch":"심화에서 단위를 빠뜨리는 경우","min":5}},"suggested_extras":["q_l7_5","g_l7_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"무게 어림왕","type":"group","goal":"여러 물건의 무게를 어림한 뒤 저울로 재어 어림 솜씨를 견주기","steps":["모둠이 필통·물병·책 세 가지를 고른다","저마다 무게를 어림해 「약 ○ g」으로 기록지에 적는다","저울에 올려 눈금 한 칸의 크기를 말하고 무게를 읽는다","잰 값과 가장 가깝게 어림한 사람을 어림왕으로 뽑는다"],"solo":["물건 세 가지의 무게를 먼저 어림해 「약 ○ g」으로 적는다","저울로 재어 잰 값을 적고 어림과의 차이를 적는다"],"materials":["가정용 저울","필통·물병·책","1 kg 설탕 봉지(기준)","기록지"],"minutes":8,"tnote":{"ask":["어림과 가장 가까웠던 물건은?","두 번째 어림은 나아졌나요?"],"watch":"저울 바늘이 멈추기 전에 읽는 모둠 — 멈출 때까지 기다리게 할 것","min":8}},"suggested_extras":["g_l7_2","t_l7_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"마트 과일 저울","scenario":{"icon":"🍎","body":"마트에서는 과일을 저울에 올려 무게만큼 값을 매겨요. 사과 1개는 약 300 g, 수박 1통은 약 5 kg이에요."},"content":"아는 무게와 견주면 **어림**을 잘할 수 있어요."},"suggested_extras":["r_l7_2","r_l7_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"빨랫비누 한 상자에는 약 100 g인 비누가 10개 들어 있어요.","challenge":"비누 상자 두 개의 무게는 약 몇 g이고, 약 몇 kg일까요?","note":"풀이: 한 상자 약 100 g × 10 = 약 1000 g · 두 상자 약 **2000 g** = 약 **2 kg**","tnote":{"ask":["한 상자는 약 몇 g인가요?","2000 g은 몇 kg인가요?"],"watch":"상자 두 개를 비누 두 개로 보고 약 200 g이라고 하는 경우","min":4}},"suggested_extras":["t_l7_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"하마의 무게는 약 2 ○ 예요. ○ 에 알맞은 단위는 무엇인가요?","a":"t"},{"q":"100 g인 비누 10개는 몇 g인가요?","a":"1000"},{"q":"어림한 무게 앞에 붙이는 말은 무엇인가요?","a":"약"}],"self":["오늘 배운 들이와 무게를 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["어림한 무게는 앞에 **「약」**을 붙여 나타내요.","① 아는 무게와 견주어 어림해요 ② 저울의 눈금 한 칸의 크기를 먼저 봐요 ③ 가벼우면 g, 무거우면 kg, 아주 무거우면 t","다음 시간에는 무게를 더하고 빼 봐요.","곰이는 비누 10개를 약 1000 g으로 어림하고 저울로 재어 보았다."],"arrows":["아는 무게와 견주어 어림","저울 한 칸 먼저","가벼우면 g · 무거우면 kg · 아주 무거우면 t"]},"suggested_extras":["r_l7_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 무게를 어림하고 「약」을 붙여 나타낼 수 있나요?","🔧 과정·기능 — 저울의 눈금을 읽을 수 있나요?","💛 가치·태도 — 어림한 값을 잰 값과 견주어 보려고 했나요?"],"prompts":["무게를 어림할 때 무엇을 기준으로 삼았나요?"]},"suggested_extras":["e_l7_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 시간엔","preview":"다음 시간에는 **무게의 덧셈과 뺄셈**을 해 봐요. 1 kg 500 g과 2 kg 300 g의 옷을 모아 기부하면 모두 얼마일까?","emoji":"👕"},"suggested_extras":["c_l7_1"]}],"extras":[{"id":"v_l7_1","type":"video","icon":"🎥","title":"무게 어림과 재기 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+3%ED%95%99%EB%85%84+2%ED%95%99%EA%B8%B0+%EB%AC%B4%EA%B2%8C+%EC%96%B4%EB%A6%BC+%EC%A0%80%EC%9A%B8+%EB%88%88%EA%B8%88+%EC%9D%BD%EA%B8%B0","description":"아는 무게와 견주어 어림하고 저울 눈금을 읽는 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l7_1","type":"fun_question","icon":"💡","title":"1 g의 기준","content":"1 g쯤 되는 물건은 무엇이 있을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_2","type":"fun_question","icon":"💡","title":"1 kg의 기준","content":"1 kg쯤 되는 물건은 무엇이 있을까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_3","type":"fun_question","icon":"💡","title":"체중계와 전자저울","content":"아주 가벼운 물건을 체중계로 재면 어떻게 될까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_4","type":"fun_question","icon":"💡","title":"합해서 어림","content":"6개와 4개를 합하면 어림에 어떻게 도움이 될까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l7_5","type":"fun_question","icon":"💡","title":"단위 고르기","content":"배의 무게는 kg과 t 중 무엇이 알맞을까요?","fit_slides":["concept","basic_problem"]},{"id":"t_l7_1","type":"tip","icon":"🧩","title":"세 기준 카드","content":"클립(1 g) · 설탕 봉지(1 kg) · 자동차(1 t) 카드를 붙여 두세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_2","type":"tip","icon":"🧩","title":"바늘 멈춤","content":"저울 바늘이 멈춘 뒤에 읽게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_3","type":"tip","icon":"🧩","title":"한 칸 먼저","content":"저울마다 한 칸의 크기가 다르니 먼저 말하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_4","type":"tip","icon":"🧩","title":"어림 기록표","content":"어림한 값 · 잰 값 · 차이 표를 쓰게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l7_5","type":"tip","icon":"🧩","title":"덧셈 예고","content":"다음 시간은 무게를 더하고 빼요. 1 kg 추와 100 g 추를 준비하세요.","fit_slides":["concept","misconception"]},{"id":"r_l7_1","type":"real_world","icon":"🌍","title":"과일 저울","content":"사과 1개는 약 300 g이에요.","fit_slides":["real_world","summary"]},{"id":"r_l7_2","type":"real_world","icon":"🌍","title":"강아지","content":"강아지는 약 10 kg이에요.","fit_slides":["real_world","summary"]},{"id":"r_l7_3","type":"real_world","icon":"🌍","title":"자동차","content":"자동차는 약 1 t이에요.","fit_slides":["real_world","summary"]},{"id":"g_l7_1","type":"game","icon":"🎮","title":"무게 어림왕","content":"어림한 값이 잰 값과 가장 가까운 사람을 뽑습니다.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l7_2","type":"game","icon":"🎮","title":"단위 스피드 퀴즈","content":"물건 이름을 들으면 g · kg · t 중 알맞은 단위를 외칩니다.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l7_1","type":"misconception","icon":"⚠️","title":"단위 아무렇게나","content":"책상을 약 15 g으로 나타내는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l7_2","type":"misconception","icon":"⚠️","title":"한 칸 크기 건너뛰기","content":"한 칸이 200 g인 저울을 100 g씩 읽는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l7_1","type":"example","icon":"📝","title":"10 kg 저울","content":"한 칸 1 kg인 저울 그림을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l7_2","type":"example","icon":"📝","title":"필통 어림","content":"약 400 g 어림과 360 g 잰 값을 나란히 적습니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l7_3","type":"example","icon":"📝","title":"단위 카드","content":"자동차 1 t · 강아지 10 kg · 김치 500 g 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l7_1","type":"checklist","icon":"✅","title":"다음 차시 준비","content":"1 kg 추·100 g 추·기부할 헌 옷 봉투. 다음 시간은 무게의 덧셈과 뺄셈을 해요.","fit_slides":["next_lesson"]}]};
